<script>const menuButton=document.getElementById('menu-button'),mobileMenu=document.getElementById('mobile-menu');const closeMenu=()=>{mobileMenu.classList.add('hidden');menuButton.setAttribute('aria-expanded','false')};menuButton.addEventListener('click',()=>{const open=!mobileMenu.classList.toggle('hidden');menuButton.setAttribute('aria-expanded',String(open))});mobileMenu.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.getElementById('strategy-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget,status=document.getElementById('form-status');if(!form.checkValidity()){form.reportValidity();status.textContent='Please complete the required fields.';status.className='text-xs text-amber-300';return}status.textContent='Thanks — your strategy request is ready for the Avenue Z team.';status.className='text-xs font-semibold text-acid';form.reset()});</script>
